func NewOwningRoleValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (OwningRoleValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing OwningRoleValue Attribute Value",
				"While creating a OwningRoleValue value, a missing attribute value was detected. "+
					"A OwningRoleValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("OwningRoleValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid OwningRoleValue Attribute Type",
				"While creating a OwningRoleValue value, an invalid attribute value was detected. "+
					"A OwningRoleValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("OwningRoleValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("OwningRoleValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra OwningRoleValue Attribute Value",
				"While creating a OwningRoleValue value, an extra attribute value was detected. "+
					"A OwningRoleValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra OwningRoleValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewOwningRoleValueUnknown(), diags
	}

	roleIdAttribute, ok := attributes["role_id"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`role_id is missing from object`)

		return NewOwningRoleValueUnknown(), diags
	}

	roleIdVal, ok := roleIdAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`role_id expected to be basetypes.StringValue, was: %T`, roleIdAttribute))
	}

	roleNameAttribute, ok := attributes["role_name"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`role_name is missing from object`)

		return NewOwningRoleValueUnknown(), diags
	}

	roleNameVal, ok := roleNameAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`role_name expected to be basetypes.StringValue, was: %T`, roleNameAttribute))
	}

	if diags.HasError() {
		return NewOwningRoleValueUnknown(), diags
	}

	return OwningRoleValue{
		RoleId:   roleIdVal,
		RoleName: roleNameVal,
		state:    attr.ValueStateKnown,
	}, diags
}

func NewOwningRoleValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) OwningRoleValue {
	object, diags := NewOwningRoleValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewOwningRoleValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t OwningRoleType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewOwningRoleValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewOwningRoleValueUnknown(), nil
	}

	if in.IsNull() {
		return NewOwningRoleValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewOwningRoleValueMust(OwningRoleValue{}.AttributeTypes(ctx), attributes), nil
}

func (t OwningRoleType) ValueType(ctx context.Context) attr.Value {
	return OwningRoleValue{}
}

var _ basetypes.ObjectValuable = OwningRoleValue{}

type OwningRoleValue struct {
	RoleId   basetypes.StringValue `tfsdk:"role_id"`
	RoleName basetypes.StringValue `tfsdk:"role_name"`
	state    attr.ValueState
}

func (v OwningRoleValue) ToTerraformValue(ctx context.Context) (tftypes.Value, error) {
	attrTypes := make(map[string]tftypes.Type, 2)

	var val tftypes.Value
	var err error

	attrTypes["role_id"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["role_name"] = basetypes.StringType{}.TerraformType(ctx)

	objectType := tftypes.Object{AttributeTypes: attrTypes}

	switch v.state {
	case attr.ValueStateKnown:
		vals := make(map[string]tftypes.Value, 2)

		val, err = v.RoleId.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["role_id"] = val

		val, err = v.RoleName.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["role_name"] = val

		if err := tftypes.ValidateValue(objectType, vals); err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		return tftypes.NewValue(objectType, vals), nil
	case attr.ValueStateNull:
		return tftypes.NewValue(objectType, nil), nil
	case attr.ValueStateUnknown:
		return tftypes.NewValue(objectType, tftypes.UnknownValue), nil
	default:
		panic(fmt.Sprintf("unhandled Object state in ToTerraformValue: %s", v.state))
	}
}

func (v OwningRoleValue) IsNull() bool {
	return v.state == attr.ValueStateNull
}

func (v OwningRoleValue) IsUnknown() bool {
	return v.state == attr.ValueStateUnknown
}

func (v OwningRoleValue) String() string {
	return "OwningRoleValue"
}

func (v OwningRoleValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	attributeTypes := map[string]attr.Type{
		"role_id":   basetypes.StringType{},
		"role_name": basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"role_id":   v.RoleId,
			"role_name": v.RoleName,
		})

	return objVal, diags
}

func (v OwningRoleValue) Equal(o attr.Value) bool {
	other, ok := o.(OwningRoleValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.RoleId.Equal(other.RoleId) {
		return false
	}

	if !v.RoleName.Equal(other.RoleName) {
		return false
	}

	return true
}

func (v OwningRoleValue) Type(ctx context.Context) attr.Type {
	return OwningRoleType{
		basetypes.ObjectType{
			AttrTypes: v.AttributeTypes(ctx),
		},
	}
}

